// @generated by:gauntlet run:anatoly-extensible-fingerprints
mod common;

use anatoly::{fingerprints::Catalog, scan::scan_configured, scan_options::ScanOptions};
use common::{Server, limits, response};
use serde_json::{Value, json};
use std::{
    fs,
    path::PathBuf,
    process::Command,
    sync::{
        Arc,
        atomic::{AtomicU64, Ordering},
    },
};

static NEXT_FILE: AtomicU64 = AtomicU64::new(0);

struct PackFile(PathBuf);

impl PackFile {
    fn new(pack: &Value) -> Self {
        let id = NEXT_FILE.fetch_add(1, Ordering::Relaxed);
        let path = std::env::temp_dir().join(format!(
            "anatoly-fingerprint-limits-{}-{id}.json",
            std::process::id()
        ));
        let file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&path)
            .unwrap();
        serde_json::to_writer(file, pack).unwrap();
        Self(path)
    }
}

impl Drop for PackFile {
    fn drop(&mut self) {
        fs::remove_file(&self.0).unwrap();
    }
}

fn pack(rules: Value) -> Value {
    json!({"schema_version":1,"technologies":[{
        "name":"Acme Framework","kind":"framework","aliases":["Acme"],
        "composer":[],"npm":[],"rules":rules
    }]})
}

fn settings(catalog: Option<&Value>) -> ScanOptions {
    let mut settings = ScanOptions {
        samples: 1,
        discover: false,
        fingerprints: catalog.map(|v| Arc::new(Catalog::with_extra_json(&v.to_string()).unwrap())),
        ..ScanOptions::default()
    };
    settings.network.no_proxy = true;
    settings
}

fn scan(server: &Server, route: &str, settings: &ScanOptions, requests: usize) -> Value {
    let mut budget = limits();
    budget.max_body = 32_768;
    budget.max_requests = requests;
    serde_json::to_value(
        scan_configured(&format!("{}{route}", server.url), budget, settings).unwrap(),
    )
    .unwrap()
}

fn technology<'a>(report: &'a Value, name: &str) -> &'a Value {
    report["technologies"]
        .as_array()
        .unwrap()
        .iter()
        .find(|t| t["name"] == name)
        .unwrap_or_else(|| panic!("missing {name}: {report}"))
}

fn assert_unknown_php(report: &Value) {
    assert!(report["version"].is_null());
    assert!(report["version_candidates"].as_array().unwrap().is_empty());
    assert_eq!(report["runtime"]["status"], "unknown");
}

#[test]
fn f01_mixed_known_and_unknown_header_products_are_both_retained_without_php_inference() {
    let server = Server::new(|_| {
        response(
            "200 OK",
            "X-Powered-By: Express/5.1.0, AcmeEngine/4.2.1\r\n",
            "application",
        )
    });

    let report = scan(&server, "", &settings(None), 1);

    assert_eq!(technology(&report, "Express")["versions"], json!(["5.1.0"]));
    assert_eq!(
        technology(&report, "AcmeEngine")["versions"],
        json!(["4.2.1"])
    );
    assert!(technology(&report, "AcmeEngine")["runtime_hint"].is_null());
    assert_unknown_php(&report);
}

#[test]
fn f01_a_provider_whose_name_starts_with_laravel_is_not_the_laravel_framework() {
    let server = Server::new(|_| {
        response(
            "200 OK",
            "X-Powered-By: LaravelMagic/12.3.4\r\n",
            "application",
        )
    });

    let report = scan(&server, "", &settings(None), 1);

    assert_eq!(
        technology(&report, "LaravelMagic")["versions"],
        json!(["12.3.4"])
    );
    assert!(
        !report["technologies"]
            .as_array()
            .unwrap()
            .iter()
            .any(|t| t["name"] == "Laravel")
    );
    assert_unknown_php(&report);
}

#[test]
fn f02_package_mapping_limits_and_duplicates_are_validated_before_any_request() {
    let server = Server::new(|_| response("200 OK", "", "must not be requested"));
    for ecosystem in ["composer", "npm"] {
        let prefix = if ecosystem == "npm" {
            "@vendor/acme"
        } else {
            "vendor/acme"
        };
        for (names, valid) in [
            (
                (0..64).map(|i| format!("{prefix}{i}")).collect::<Vec<_>>(),
                true,
            ),
            (
                (0..65).map(|i| format!("{prefix}{i}")).collect::<Vec<_>>(),
                false,
            ),
            (vec![prefix.into(), prefix.into()], false),
        ] {
            let mut catalog = pack(json!([]));
            catalog["technologies"][0][ecosystem] = json!(names);
            let file = PackFile::new(&catalog);

            let output = Command::new(env!("CARGO_BIN_EXE_anatoly"))
                .args([
                    "scan",
                    &server.url,
                    "--profile",
                    "quick",
                    "--dry-run",
                    "--json",
                    "--no-proxy",
                ])
                .arg("--fingerprints")
                .arg(&file.0)
                .output()
                .unwrap();

            assert_eq!(
                output.status.success(),
                valid,
                "{ecosystem}: {}",
                String::from_utf8_lossy(&output.stderr)
            );
            assert!(server.paths.lock().unwrap().is_empty());
        }
    }
}

#[test]
fn f03_npm_lock_packages_report_production_versions_and_skip_development_entries() {
    let server = Server::new(|_| {
        response(
            "200 OK",
            "Content-Type: application/json\r\n",
            r#"{
        "lockfileVersion":3,"packages":{
            "node_modules/next":{"version":"15.4.3"},
            "node_modules/dev-tool/node_modules/next":{"version":"99.0.0","dev":true}
        }}"#,
        )
    });

    let report = scan(&server, "package-lock.json", &settings(None), 1);

    assert_eq!(
        technology(&report, "Next.js")["versions"],
        json!(["15.4.3"])
    );
    assert!(
        technology(&report, "Next.js")["observations"]
            .as_array()
            .unwrap()
            .iter()
            .all(|o| o["version"] == "15.4.3")
    );
    assert_unknown_php(&report);
}

#[test]
fn f03_npm_requirements_and_dev_only_packages_are_not_installed_version_evidence() {
    for (route, body, present) in [
        (
            "package.json",
            r#"{"dependencies":{"next":"^15.4.3"}}"#,
            true,
        ),
        (
            "package.json",
            r#"{"devDependencies":{"next":"15.4.3"}}"#,
            false,
        ),
        (
            "package-lock.json",
            r#"{"packages":{"node_modules/next":{"version":"15.4.3","dev":true}}}"#,
            false,
        ),
    ] {
        let server =
            Server::new(move |_| response("200 OK", "Content-Type: application/json\r\n", body));

        let report = scan(&server, route, &settings(None), 1);

        assert_eq!(
            report["technologies"]
                .as_array()
                .unwrap()
                .iter()
                .any(|t| t["name"] == "Next.js"),
            present
        );
        if present {
            assert!(
                technology(&report, "Next.js")["versions"]
                    .as_array()
                    .unwrap()
                    .is_empty()
            );
        }
        assert_unknown_php(&report);
    }
}

#[test]
fn f04_opaque_broad_header_captures_never_export_raw_values_as_versions() {
    let catalog = pack(
        json!([{"channel":"header","key":"x-acme-version","pattern":"^(.+)$","version_group":1}]),
    );
    let settings = settings(Some(&catalog));
    for value in [
        "4SECRET_PRIVATE_FIXTURE",
        "4.2.1;PRIVATE_FIXTURE",
        "4.2.1/PRIVATE_FIXTURE",
        ">=4.2.1PRIVATE_FIXTURE",
        "1234567.2PRIVATE_FIXTURE",
    ] {
        let header = format!("X-Acme-Version: {value}\r\n");
        let server = Server::new(move |_| response("200 OK", &header, "application"));

        let report = scan(&server, "", &settings, 1);

        assert!(
            technology(&report, "Acme Framework")["versions"]
                .as_array()
                .unwrap()
                .is_empty()
        );
        assert!(!report.to_string().contains("PRIVATE_FIXTURE"), "{report}");
        assert_unknown_php(&report);
    }
}

#[test]
fn f04_version_capture_components_and_suffixes_have_explicit_boundaries() {
    let catalog = pack(
        json!([{"channel":"header","key":"x-acme-version","pattern":"^(.+)$","version_group":1}]),
    );
    let settings = settings(Some(&catalog));
    for (value, expected) in [
        ("1.2", true),
        ("12.34.56.78", true),
        ("123456.2.3", true),
        ("1.2.3-rc.1", true),
        ("1234567.2", false),
        ("1.2.3.4.5", false),
        ("1", false),
        ("1..2", false),
        (
            "1.2-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
            false,
        ),
    ] {
        let header = format!("X-Acme-Version: {value}\r\n");
        let server = Server::new(move |_| response("200 OK", &header, "application"));

        let report = scan(&server, "", &settings, 1);

        assert_eq!(
            !technology(&report, "Acme Framework")["versions"]
                .as_array()
                .unwrap()
                .is_empty(),
            expected,
            "{value}"
        );
        assert_unknown_php(&report);
    }
}

#[test]
fn f05_html_selection_and_text_limits_are_visible_as_incomplete_analysis() {
    let catalog = pack(
        json!([{"channel":"html","selector":".acme-marker","pattern":r"^(4\.2\.1)$","version_group":1}]),
    );
    let settings = settings(Some(&catalog));
    for body in [
        format!(
            "{}<div class='acme-marker'>4.2.1</div>",
            "<div class='acme-marker'>none</div>".repeat(32)
        ),
        format!("<div class='acme-marker'>{}4.2.1</div>", "x".repeat(4097)),
    ] {
        let server = Server::new(move |_| response("200 OK", "", &body));

        let report = scan(&server, "", &settings, 1);

        assert_eq!(report["observations"][0]["truncated"], false);
        assert_eq!(report["analysis"]["coverage_complete"], false);
        assert!(
            report["analysis"]["gaps"]
                .as_array()
                .unwrap()
                .iter()
                .any(|gap| gap.as_str().unwrap().to_ascii_lowercase().contains("html")),
            "{report}"
        );
        assert_unknown_php(&report);
    }
}

#[test]
fn f06_global_technology_cap_reports_truncation_even_when_the_request_plan_completes() {
    let server = Server::new(|path| {
        let page = path.trim_matches('/').parse::<usize>().unwrap_or(0);
        let declarations = (0..16)
            .map(|i| format!("Engine{page}_{i}/4.2.1"))
            .collect::<Vec<_>>()
            .join(", ");
        response(
            "200 OK",
            &format!("X-Powered-By: {declarations}\r\n"),
            "application",
        )
    });
    let mut settings = settings(None);
    settings.discover = true;
    settings.paths = (1..=16).map(|i| i.to_string()).collect();

    let report = scan(&server, "", &settings, 17);

    let technologies = report["technologies"].as_array().unwrap();
    assert_eq!(technologies.len(), 256);
    assert!(technologies.iter().any(|t| t["truncated"] == true));
    assert_eq!(report["analysis"]["diagnostics_requested"], 16);
    assert_eq!(report["analysis"]["diagnostics_completed"], 16);
    assert_eq!(report["requests_sent"], 17);
    assert_eq!(report["analysis"]["coverage_complete"], false);
    assert!(!report["analysis"]["gaps"].as_array().unwrap().is_empty());
    assert_eq!(server.paths.lock().unwrap().len(), 17);
    assert_unknown_php(&report);
}
